-- ====================================================================
-- OMNIPOLL SPATIAL DATA INTELLIGENCE CORE
-- BASE DE DATOS COMPLETA PARA PRODUCCIÓN (CPANEL / BANAHOSTING / MYSQL)
-- Incluye: 16 tablas, RBAC, 6 Usuarios, 5 Encuestas (incluye CCAVX024), 512 Respuestas y 1,874 Distritos INEI
-- Fecha: 2026-09-25 18:58:02
-- ====================================================================

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '-05:00';

-- ------------------------------------------------------------
-- 1. LIMPIEZA PREVIA (DROP TABLES)
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `auditoria_aprobaciones`;
DROP TABLE IF EXISTS `detalle_respuestas`;
DROP TABLE IF EXISTS `respuestas_encuesta`;
DROP TABLE IF EXISTS `opciones_pregunta`;
DROP TABLE IF EXISTS `preguntas`;
DROP TABLE IF EXISTS `secciones`;
DROP TABLE IF EXISTS `encuestas`;
DROP TABLE IF EXISTS `distritos`;
DROP TABLE IF EXISTS `provincias`;
DROP TABLE IF EXISTS `departamentos`;
DROP TABLE IF EXISTS `usuario_encuestas`;
DROP TABLE IF EXISTS `usuarios`;
DROP TABLE IF EXISTS `rol_permisos`;
DROP TABLE IF EXISTS `permisos`;
DROP TABLE IF EXISTS `modulos`;
DROP TABLE IF EXISTS `roles`;

-- ------------------------------------------------------------
-- 2. CREACIÓN DE TABLAS (DDL)
-- ------------------------------------------------------------

-- Tabla: roles
CREATE TABLE `roles` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `badge_color` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'primary',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: modulos
CREATE TABLE `modulos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icono` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'folder',
  `orden` int NOT NULL DEFAULT '1',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: permisos
CREATE TABLE `permisos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `modulo_id` int NOT NULL,
  `codigo` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`),
  KEY `modulo_id` (`modulo_id`),
  CONSTRAINT `permisos_ibfk_1` FOREIGN KEY (`modulo_id`) REFERENCES `modulos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: rol_permisos
CREATE TABLE `rol_permisos` (
  `rol_id` int NOT NULL,
  `permiso_id` int NOT NULL,
  PRIMARY KEY (`rol_id`,`permiso_id`),
  KEY `permiso_id` (`permiso_id`),
  CONSTRAINT `rol_permisos_ibfk_1` FOREIGN KEY (`rol_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rol_permisos_ibfk_2` FOREIGN KEY (`permiso_id`) REFERENCES `permisos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: usuarios
CREATE TABLE `usuarios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rol` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'encuestador',
  `rol_id` int DEFAULT NULL,
  `cargo` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avatar_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `auth_token` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: usuario_encuestas
CREATE TABLE `usuario_encuestas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuario_id` int NOT NULL,
  `encuesta_id` int NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_usuario_encuesta` (`usuario_id`,`encuesta_id`),
  KEY `encuesta_id` (`encuesta_id`),
  CONSTRAINT `usuario_encuestas_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `usuario_encuestas_ibfk_2` FOREIGN KEY (`encuesta_id`) REFERENCES `encuestas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: departamentos
CREATE TABLE `departamentos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo_ubigeo` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo_ubigeo` (`codigo_ubigeo`),
  KEY `idx_dep_codigo` (`codigo_ubigeo`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: provincias
CREATE TABLE `provincias` (
  `id` int NOT NULL AUTO_INCREMENT,
  `departamento_id` int NOT NULL,
  `codigo_ubigeo` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo_ubigeo` (`codigo_ubigeo`),
  KEY `idx_prov_dep` (`departamento_id`),
  KEY `idx_prov_codigo` (`codigo_ubigeo`),
  CONSTRAINT `provincias_ibfk_1` FOREIGN KEY (`departamento_id`) REFERENCES `departamentos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=197 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: distritos
CREATE TABLE `distritos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `provincia_id` int NOT NULL,
  `codigo_ubigeo` varchar(6) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo_ubigeo` (`codigo_ubigeo`),
  KEY `idx_dist_prov` (`provincia_id`),
  KEY `idx_dist_codigo` (`codigo_ubigeo`),
  CONSTRAINT `distritos_ibfk_1` FOREIGN KEY (`provincia_id`) REFERENCES `provincias` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1875 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: encuestas
CREATE TABLE `encuestas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `titulo` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `norma_tecnica` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `categoria` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Censo & Servicios',
  `version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'v1.0',
  `estado` enum('borrador','pendiente','aprobada','rechazada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'borrador',
  `tiempo_estimado_min` int NOT NULL DEFAULT '5',
  `total_pasos` int NOT NULL DEFAULT '4',
  `creador_id` int DEFAULT NULL,
  `resolucion_aprobacion` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `motivo_rechazo` text COLLATE utf8mb4_unicode_ci,
  `branding_json` json DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`),
  KEY `creador_id` (`creador_id`),
  KEY `idx_encuesta_estado` (`estado`),
  KEY `idx_encuesta_codigo` (`codigo`),
  CONSTRAINT `encuestas_ibfk_1` FOREIGN KEY (`creador_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: secciones
CREATE TABLE `secciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encuesta_id` int NOT NULL,
  `numero_orden` int NOT NULL,
  `titulo` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_sec_encuesta` (`encuesta_id`,`numero_orden`),
  CONSTRAINT `secciones_ibfk_1` FOREIGN KEY (`encuesta_id`) REFERENCES `encuestas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: preguntas
CREATE TABLE `preguntas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encuesta_id` int NOT NULL,
  `seccion_id` int DEFAULT NULL,
  `numero_orden` int NOT NULL,
  `tipo` enum('texto','opcion_unica','opcion_multiple','escala_nps','ubigeo_cascada','calificacion') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'opcion_unica',
  `enunciado` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `ayuda` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `es_requerida` tinyint(1) NOT NULL DEFAULT '1',
  `configuracion_json` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `seccion_id` (`seccion_id`),
  KEY `idx_preg_encuesta` (`encuesta_id`,`numero_orden`),
  CONSTRAINT `preguntas_ibfk_1` FOREIGN KEY (`encuesta_id`) REFERENCES `encuestas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `preguntas_ibfk_2` FOREIGN KEY (`seccion_id`) REFERENCES `secciones` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: opciones_pregunta
CREATE TABLE `opciones_pregunta` (
  `id` int NOT NULL AUTO_INCREMENT,
  `pregunta_id` int NOT NULL,
  `numero_orden` int NOT NULL,
  `etiqueta` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `valor` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icono` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_opc_pregunta` (`pregunta_id`,`numero_orden`),
  CONSTRAINT `opciones_pregunta_ibfk_1` FOREIGN KEY (`pregunta_id`) REFERENCES `preguntas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: respuestas_encuesta
CREATE TABLE `respuestas_encuesta` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encuesta_id` int NOT NULL,
  `codigo_sesion` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `departamento_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provincia_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `distrito_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `departamento_codigo` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provincia_codigo` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `distrito_codigo` varchar(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ubigeo_completo` varchar(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tiempo_llenado_segundos` int NOT NULL DEFAULT '0',
  `satisfaccion` int DEFAULT NULL,
  `nps` int DEFAULT NULL,
  `ip_origen` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado` enum('completada','parcial') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'completada',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo_sesion` (`codigo_sesion`),
  KEY `idx_resp_encuesta` (`encuesta_id`),
  KEY `idx_resp_ubigeo` (`ubigeo_completo`),
  CONSTRAINT `respuestas_encuesta_ibfk_1` FOREIGN KEY (`encuesta_id`) REFERENCES `encuestas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=513 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: detalle_respuestas
CREATE TABLE `detalle_respuestas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `respuesta_encuesta_id` int NOT NULL,
  `pregunta_id` int NOT NULL,
  `valor_texto` text COLLATE utf8mb4_unicode_ci,
  `valor_numero` decimal(10,2) DEFAULT NULL,
  `opciones_json` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_det_resp` (`respuesta_encuesta_id`),
  KEY `idx_det_preg` (`pregunta_id`),
  CONSTRAINT `detalle_respuestas_ibfk_1` FOREIGN KEY (`respuesta_encuesta_id`) REFERENCES `respuestas_encuesta` (`id`) ON DELETE CASCADE,
  CONSTRAINT `detalle_respuestas_ibfk_2` FOREIGN KEY (`pregunta_id`) REFERENCES `preguntas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2018 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabla: auditoria_aprobaciones
CREATE TABLE `auditoria_aprobaciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encuesta_id` int NOT NULL,
  `usuario_id` int DEFAULT NULL,
  `usuario_nombre` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `accion` enum('aprobada','rechazada','solicitud_cambio','enviada_revision') COLLATE utf8mb4_unicode_ci NOT NULL,
  `comentario` text COLLATE utf8mb4_unicode_ci,
  `resolucion_oficial` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `usuario_id` (`usuario_id`),
  KEY `idx_aud_encuesta` (`encuesta_id`),
  CONSTRAINT `auditoria_aprobaciones_ibfk_1` FOREIGN KEY (`encuesta_id`) REFERENCES `encuestas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `auditoria_aprobaciones_ibfk_2` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

