-- Datos para la tabla: encuestas (5 registros)
INSERT INTO `encuestas` (`id`, `codigo`, `titulo`, `descripcion`, `norma_tecnica`, `categoria`, `version`, `estado`, `tiempo_estimado_min`, `total_pasos`, `creador_id`, `resolucion_aprobacion`, `motivo_rechazo`, `branding_json`, `created_at`, `updated_at`) VALUES
  ('1', 'CENSO-PE-2025-Q1', 'Censo Nacional de Conectividad & Servicios Digitales 2025', 'Instrumento de recolección georreferenciado para el diseño de infraestructura de telecomunicaciones e inclusión digital.', 'DS-024-INEI-PE', 'Censo & Conectividad', 'v3.4-PRO', 'aprobada', '4', '4', '1', 'RES-DIR-088-2025/MTC', NULL, NULL, '2026-09-20 10:00:00', '2026-09-25 10:07:10'),
  ('2', 'POLL-TECH-2025-02', 'Clima Laboral y Adopción de Inteligencia Artificial en Entidades Públicas', 'Estudio sobre alfabetización digital, impacto de asistentes de IA generativa y ciberseguridad en el sector estatal.', 'PCM-SGTD-004-2025', 'Innovación Pública & RRHH', 'v2.1', 'pendiente', '5', '5', '2', NULL, NULL, NULL, '2026-09-21 14:15:00', '2026-09-25 10:07:10'),
  ('3', 'SALUD-SUR-2025-Q3', 'Evaluación de Calidad de Atención y Tiempos de Espera en Red de Salud Sur', 'Sondeo de satisfacción de pacientes, disponibilidad de medicamentos y atención en triaje en hospitales del Minsa y EsSalud.', 'NTS-142-MINSA/DGAIN', 'Salud Pública', 'v1.0', 'aprobada', '4', '4', '1', 'RES-MINSA-451-2025', NULL, NULL, '2026-09-18 09:30:00', '2026-09-25 10:07:10'),
  ('4', 'FINTECH-PE-2025-Q1', 'Inclusión Financiera y Uso de Billeteras Digitales en Comunidades Rurales', 'Estudio sobre adopción de pagos digitales (Yape, Plin) y brecha de cajeros automáticos en zonas andinas.', 'SBS-CIRC-B-2240', 'Inclusión Financiera', 'v1.2', 'rechazada', '6', '5', '2', NULL, 'Requiere ampliar el bloque de preguntas de ciberseguridad y consentimiento explícito conforme a la Ley 29733 de Protección de Datos Personales.', NULL, '2026-09-22 09:15:00', '2026-09-25 10:07:10'),
  ('24', 'CCAVX024', 'CCAV', 'Encuesta oficial de asistencia a sedes, pertenencia a redes de comunidad y distribución distrital.', 'CCAV-DIR-2026', 'Comunidad & Sedes', 'v2.0-PRO', 'aprobada', '3', '4', '1', 'RES-CCAV-2026-001', NULL, '{\"logo_url\": \"assets/logo-symbol.svg\", \"font_family\": \"Outfit\", \"accent_color\": \"#10b981\", \"survey_title\": \"Encuesta Oficial CCAV 2026\", \"primary_color\": \"#0ea5e9\", \"secondary_color\": \"#6366f1\"}', '2026-09-24 10:00:00', '2026-09-25 11:55:04');

